sys_extension_point.example:
var AESAnnouncementExtension = Class.create();
AESAnnouncementExtension.prototype = {
    initialize: function() {},

    transformAnnouncement: function(announcement, gr, options) {
        // Add or modify custom Announcement data.
        announcement.custom_field = gr.getValue('u_custom_field');

        return announcement;
    },

    process: function( /*array*/ data) {
        data.push("new entry");
        return data;
    },

    type: 'AESAnnouncementExtension'
};
